protected InventTable inventTable()
{
    switch(element.args().dataset())
    {
        case tableNum(InventTable):
            return element.args().record();

        case tableNum(ReqTrans):
            callerReqTrans = element.args().record();
            return callerReqTrans.inventTable();

        case tableNum(ProdTable):
            ProdTable prodTable = element.args().record();
            return prodTable.inventTable();
    }
    return null;
}

void init()
{
    super();
    if (element.args())
    {
        callerInventTable = this.inventTable();
    }

    if (!callerInventTable)
    {
        throw error(Error::missingFormActiveBuffer(formstr(AVARouteBOMInvent), tablestr(InventTable)));
    }

    if (!callerInventTable.isFormulaOrBOMAllowed())
    {
        throw error(strfmt("@PRO2616", callerInventTable.ItemId));
    }

    if (!callerInventTable.inventItemType().canHaveRoutes())
    {
        throw error(strFmt("@SYS22874", callerInventTable.ItemId));
    }

    this.inititemid();

    _list = ListViewMonthlyValues;

    _list.addColumn(1,new FormListColumn("@NDX:NDXConsump",1, 100));
    _list.addColumn(2,new FormListColumn("@NDX:NDXLastYear",2, 100));
    _list.addColumn(3,new FormListColumn("@NDX:NDXCurrent",3, 100));

    _listYear   = ListViewYearlyValues;

    _listYear.addColumn(1, new FormListColumn("@NDX:NDXYear",1));
    _listYear.addColumn(2, new FormListColumn("@NDX:NDXConsump",2, 100));

    reqTransForm = AVAReqTransFormOverview::newFormRun(element);
    //reqTransForm.parmCtrlGridReqDate(reqTrans_ReqDate);
    reqTransForm.parmCtrlTabTrans(tabReqTrans);
    reqTransForm.parmCtrlTabSum(ctrlTabSum);

    reqTransForm.parmTmpReqInventDim(tmpReqInventDim);

    //reqTransForm.parmCtrlGroupSettlement(groupSettlement);

    //reqTransForm.parmCtrlTabPagePeriod(tabPeriod);
    //reqTransForm.parmReqTmpPeriodQty(reqTmpPeriodQty);
    //reqTransForm.parmCtrlGraphPeriod(graphPeriod);
    //reqTransForm.parmCtrlGridPeriod(gridPeriod);

    reqTransForm.formInitPost();

    reqTransForm.parmPlanFilterControl(PlanFilter);
    //reqTransForm.parmPeriodChartTypeMenuButtonGroup(periodModeGraphType);
    //reqTransForm.parmPeriodTemplateMenuButtonGroup(periodTemplate);
    //reqTransForm.initSelectionFilters();

    this.onModifiedPlanFilter();
}

