}

private void initItemId()
{
    if (callerReqTrans)
    {
        ItemId = callerreqtrans.ItemId;
        InventSiteId = callerreqtrans.inventDim().InventSiteId;
        UnitID = callerReqTrans.inventUnitId();
    }
    else
    {
        WHSInventFixedLocation whsInventFixedLocation;
        itemId = callerInventTable.ItemId;
        select firstonly WHSInventFixedLocation where whsInventFixedLocation.ItemId == itemId;
        inventSiteId = whsInventFixedLocation.InventSiteId;
        unitId = callerInventTable.inventUnitId();
    }
    if (!inventSiteId)
    {
        inventSiteId = inventItemInventSetup::findDefault(itemId).inventDimDefault().InventSiteId;
    }
}

void setCurrentValues()
{
    NDXItemScopeHistory        itemScopeHistory = NDXItemScopeHistory::construct();

    itemScopeHistory.parmItemId(itemId);
    itemScopeHistory.parmInventSiteId(inventSiteId);
    itemScopeHistory.parmCurYear(curYear);

    [ConsumpCurMonth,
     ConsumpMedian,
     PhysOnHand,
     AvailOnHand,
     PhysScope,
     AvailScope,
     ConsumpCurMonthInventSite,
     PhysScopeInventSite,
     AvailScopeInventSite] = itemScopeHistory.setCurrentValues();
}

void setListViewMonthlyValues()
{
    KCS_ItemScopeHistory    curScopeHistory, prevScopeHistory;
    int                     monthCounter;
    yr                      prevYear;
    FormListItem            fli;
    int                     idx;

    ListViewMonthlyValues.deleteAll();

    prevYear    = curYear - 1;

    for(monthCounter = 1; monthCounter <= 12; monthCounter++)
    {
        curScopeHistory     = KCS_ItemScopeHistory::find(ItemId, curYear, monthCounter);
        prevScopeHistory    = KCS_ItemScopeHistory::find(ItemId, prevYear, monthCounter);

        fli = new FormListItem(mthname(monthCounter),1);
        fli.idx(monthCounter);
        idx = ListViewMonthlyValues.addItem(fli);
        ListViewMonthlyValues.setText(idx, num2str(abs(prevScopeHistory.ConsumpSum),0,2,2,1), 1);
        ListViewMonthlyValues.setText(idx, num2str(abs(curScopeHistory.ConsumpSum),0,2,2,1), 2);
    }

}

void setListViewYearlyValues()
{
    KCS_ItemScopeHistory    curScopeHistory;
    yr                      minYear;
    FormListItem            fli;
    int                     idx;

    ListViewYearlyValues.deleteAll();

    select firstOnly curScopeHistory order by HistoryDate
                                where curScopeHistory.ItemId == ItemId;

    minYear = year(curScopeHistory.HistoryDate);
    if (!curScopeHistory.RecId)
    {
        minYear = curYear;
    }

    if ((curYear - 6) > minYear)
    {
        minYear = curYear - 6;
    }

    while (minYear <= curYear)
    {
        select sum(ConsumpSum) from curScopeHistory where curScopeHistory.ItemId == ItemId
                                                   && curScopeHistory.Year   == minYear;

        fli = new FormListItem(int2str(minYear),1);
        fli.idx(minYear);
        idx = ListViewYearlyValues.addItem(fli);
        ListViewYearlyValues.setText(idx, num2str(abs(curScopeHistory.ConsumpSum),0,2,2,1), 1);
        minYear++;
    }
}

public ReqSetupDim reqSetupDim(
    ReqItemTable    _reqItemTable      = reqItemTable,
    InventDim       _inventDim         = inventDim,
    boolean         _setCovInventDimId = true,
    boolean         _reread            = false)
{
    str                 dimKey;
    ReqSetupDimForm     reqSetupDimForm;



    if (   !reqSetup
        || reqSetup.itemId() != _reqItemTable.ItemId)
    {
        reqSetup = ReqSetup::newItemId(_reqItemTable.ItemId);
        this.initMapCache();
    }

    if (!mapReqSetupDimForm)
    {
        this.initMapCache();
    }

    dimKey = _inventDim.mapKeyCov();

    if (!mapReqSetupDimForm.exists(dimKey) || _reread)
    {
        reqSetupDimForm = ReqSetupDimForm::newfromForm(reqSetup,_reqItemTable);
        mapReqSetupDimForm.insert(dimKey, reqSetupDimForm);
        reqSetupDimForm.showInfolog();
    }
    else
    {
        reqSetupDimForm = mapReqSetupDimForm.lookup(dimKey);
    }

    reqSetupDimForm.update(_reqItemTable);
    return reqSetupDimForm;
}

