public void executeQuery()
{
    QueryBuildDataSource    qbds;

    qbds = Inventsum_ds.queryBuildDataSource();
    //SysQuery::findOrCreateRange(qbds, fieldNum(InventSum, ItemId)).value(callerInventTable.ItemId);
    SysQuery::findOrCreateGroupByField(InventSum_q, qbds, fieldNum(InventSum, InventSiteId));
    SysQuery::findOrCreateGroupByField(InventSum_q, qbds, fieldNum(InventSum, InventLocationId));
    qbds.addSelectionField(fieldNum(InventSum, PhysicalInvent), SelectionField::Sum);
    qbds.addSelectionField(fieldNum(InventSum, ReservPhysical), SelectionField::Sum);
    qbds.addSelectionField(fieldNum(InventSum,  AvailPhysical), SelectionField::Sum);
    qbds.addSelectionField(fieldNum(InventSum, Ordered), selectionField::Sum);
    qbds.addSelectionField(fieldNum(InventSum, OnOrder), SelectionField::Sum);
    qbds.addSelectionField(fieldNum(InventSum, ReservOrdered), SelectionField::Sum);
    qbds.addSelectionField(fieldNum(InventSum, AvailOrdered), SelectionField::Sum); 

    super();
}

