void findCaller()
{
    TmpReqInventDim        tmpReqInventDimLocal;

    if (element.args().dataset())
    {
        reqTransCaller = ReqTrans::findCommon(
        ReqPlan::findReqPlanId(reqTransForm.parmReqPlanId()).findActiveVersion().RecId,
        element.args().record());

        if (reqTransCaller.RecId)

        {
            tmpReqInventDimLocal = TmpReqInventDim::findInventDimId(reqTransCaller.CovInventDimId,tmpReqInventDim);
            tmpReqInventDim_ds.findRecord(tmpReqInventDimLocal);

            if (element.args().lookupRecord() && element.args().lookupRecord().TableId != tableNum(TmpReqInventDim))
            {
                element.args().lookupRecord(tmpReqInventDimLocal);
            }
        }  
    }
}

display PdsCWReqQty cwQty(ReqTrans _reqTrans)
{
    return PdsCatchWeight::cwQty(_reqTrans.ItemId, reqTransForm.displayTransQty(_reqTrans));
}

public void executeQuery()
{
    //reqTransForm.reqTransDSExecuteQueryPre();
    QueryBuildDataSource    qbsTrans = reqTrans_ds.queryBuildDataSource();
    QueryBuildRange rangeItemId = SysQuery::findOrCreateRange(qbsTrans, fieldNum(ReqTrans, ItemId));

    rangeItemId.value(queryValue(itemId));

    SysQuery::findOrCreateRange(qbsTrans, fieldNum(ReqTrans, PlanVersion)).value(queryValue(ReqPlan::findReqPlanId(reqTransForm.parmReqPlanId()).findActiveVersion().RecId));

    qbsTrans.sortClear();

    qbsTrans.addSortField(fieldnum(ReqTrans,ReqDate));
    qbsTrans.addSortField(fieldnum(ReqTrans,Direction));
    qbsTrans.addSortField(fieldnum(ReqTrans,RecId));

    qbsTrans.addSortIndex(indexnum(ReqTrans,ItemIdx));
    qbsTrans.indexIsHint(true);


    super();

    //reqTransForm.reqTransDSExecuteQueryPost();
}

public void linkActive()
{
    super();

    if (reqTransCaller &&
        reqTransCaller.CovInventDimId == tmpReqInventDim.CovInventDimId)
    {
        // The code is using findRecord() for the following reasons:
        // 1. New API positionToRecord() throws exceptions in current scenario.
        // 2. Focus will not be on the expected line if using lookupRecord().
        // 3. Sorting will not work if using lookupField() and lookupValue().
        // 4. This approach secures that both sorting and setting focus behave properly.
        reqTrans_ds.findRecord(reqTransCaller);

        reqTransCaller = null;
    }  
}

public void executeQuery()
{
    ReqItemTable    reqItemTableLocal;

    super();

    this.setPosition(1);

    reqItemTableLocal = reqItemTable_ds.getFirst(0,false);

    while (reqItemTableLocal)
    {
        reqItemTableLocal.initFromReqSetupDim(element.reqSetupDim(reqItemTableLocal,reqItemTableLocal.inventDim(),false));
        reqItemTableLocal = reqItemTable_ds.getNext();
    }
}

public int active()
{
    int ret;

    ret = super();

    this.executeQuery();

    return ret;
}

public boolean modified()
{
    boolean ret;

    ret = super();

    reqTransForm.planIdSelectionChanged(this);

    element.onModifiedPlanFilter();

    return ret;
}
